import type { ComponentProps, ReactNode } from "react";
import { cn } from "./lib/cn";
import "./aspect-ratio.css";

export function AspectRatio({
  ratio = 1,
  animated = true,
  children,
  className,
  ...props
}: Omit<ComponentProps<"div">, "children"> & {
  ratio?: number;
  animated?: boolean;
  children?: ReactNode;
}) {
  const safe = Number.isFinite(ratio) && ratio > 0 ? ratio : 1;
  return (
    <div
      data-slot="aspect-ratio"
      data-animated={animated}
      className={cn("relative w-full overflow-hidden", className)}
      style={{ aspectRatio: String(safe) }}
      {...props}
    >
      {children}
    </div>
  );
}

export function AspectRatioImage({
  alt,
  className,
  ...props
}: ComponentProps<"img"> & { alt: string }) {
  return (
    <img
      alt={alt}
      data-slot="aspect-ratio-image"
      className={cn("absolute inset-0 size-full object-cover", className)}
      {...props}
    />
  );
}

import { clsx, type ClassValue } from "clsx";
import { extendTailwindMerge } from "tailwind-merge";

const twMerge = extendTailwindMerge({
  extend: { theme: { radius: ["control", "surface", "overlay"], shadow: ["overlay"] } },
});

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}

/* aspect-ratio.tsx's styles; it imports this file. Edit freely. */
@layer theme, base, components, utilities;

@layer components {
  [data-slot="aspect-ratio"][data-animated="true"] {
    transition: aspect-ratio var(--duration-normal) var(--ease-settle);
  }

  @media (prefers-reduced-motion: reduce) {
    [data-slot="aspect-ratio"][data-animated="true"] {
      transition: aspect-ratio 180ms var(--ease-settle);
    }
  }
}
